/* Kickoff, shared alignment and facilitator-owned framing board. */
window.createKickoffFeature = function(api) {
  'use strict';
  const {$,esc,getProject:project,newId,toast,download,save,render,updateChrome,syncContext,recordReadiness,stageNavigation}=api;
  const clone=x=>JSON.parse(JSON.stringify(x));
  const text=(v,max=4000)=>typeof v==='string'?v.slice(0,max):'';
  const choice=(v,values)=>values.includes(v)?v:'';
  const now=()=>new Date().toISOString();
  const validDate=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v+'T12:00:00Z'))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;
  const sections=[
    {id:'today',title:'What we know so far',minutes:5,tip:'Keep facts with their sources. Separate assumptions, unclear points and decisions that are already fixed.',lanes:['We know','We assume','We are unclear about','Already decided / fixed']},
    {id:'problem',title:'What problem are we trying to solve?',minutes:25,tip:'Connect the project decision, the user difficulty and its business consequence. If you hear a solution, ask which problem it solves.',lanes:['Project team','Users','Business']},
    {id:'success',title:'What does success look like?',minutes:20,tip:'Start with the outcome, then the observable signal, possible measure and reference. Keep an unknown baseline visible.',lanes:['Expected outcome','Observable signal','Possible measure','Reference / baseline']},
    {id:'evidence',title:'What do we need to verify?',minutes:20,tip:'Turn important uncertainty into an answerable question. Check existing evidence before planning new research.',lanes:['What needs checking?','Why does it matter?','What would answer it?','Evidence to reuse']},
    {id:'reach',title:'Who are the users and how can we reach them?',minutes:20,tip:'Identify actual users and missing profiles. Separate population size from a later research sample; record proxy limitations.',lanes:['User group / profile','Access','Route to users']},
    {id:'people',title:'Who do we need to involve?',minutes:10,tip:'Keep the people needed for decisions, knowledge, access and approvals. Include dependencies and possible blockers.',lanes:['Person / role','Why they matter','Contribution needed']},
    {id:'next',title:'What do we do next?',minutes:10,tip:'Choose the first useful actions. Link each to an owner and date, with any blocker or specialist support.',lanes:['Next useful action','Owner','Date / milestone']}
  ];
  const sectionById=id=>sections.find(s=>s.id===id)||sections[0];
  const expected={problem:'Clear problem framing',unknowns:'Hypotheses and unknowns listed',users:'User population identified and included',objectives:'Design and business objectives defined',alignment:'Project team aligned'};
  const warningLabels={noUsers:'Users absent or proxies unrelated to the population',population:'Population is unclear or too broad',purpose:'Project purpose or objectives are unclear',hypotheses:'Design objectives or hypotheses are missing',success:'Success is unknown or cannot be measured',deliverables:'Deliverables are unclear or only UI oriented'};
  const alignmentLabels={fixed:'What is already fixed?',open:'What can still change?',decision:'Which decision still needs evidence?',risk:'Which risk should we reduce?',access:'What user access is realistic?',output:'What useful output can we agree?',deadline:'When is the decision needed?',limitations:'What will remain uncertain?',rights:'Who decides, approves or helps unblock the work?'};
  const limitedLabels={scope:'Priority decision / flow and scope',effort:'Agreed effort budget (person-days)',deliverables:'Agreed deliverables',risks:'Unvalidated assumptions and accepted risks',followup:'Later validation / measurement and owner'};
  const organisationOptions=[['','Not decided yet'],['phases','Fixed phases / timeboxed'],['sprints','Agile sprints'],['flow','Continuous flow'],['hybrid','Hybrid'],['other','Other']];
  let session=null,section='today',overview=false,undo=null,drag=null,timer=null,seconds=0;
  const cleanHistory=items=>(Array.isArray(items)?items:[]).filter(x=>x&&typeof x.at==='string').slice(-100).map(x=>({at:text(x.at,80),field:text(x.field,100),value:text(x.value)}));
  function clean(raw){
    const s=raw&&typeof raw==='object'?raw:{},b=s.board||{},m=s.mandate||{};
    const cards=[],seen=new Set();
    for(const c of (Array.isArray(b.cards)?b.cards:[]).slice(0,200)){
      if(!c||typeof c.id!=='string'||!c.id||c.id.length>100||!/^[A-Za-z0-9_-]+$/.test(c.id)||seen.has(c.id))continue;
      seen.add(c.id);const sec=sectionById(c.section),lane=Math.max(0,Math.min(sec.lanes.length-1,Math.floor(Number(c.lane)||0)));
      cards.push({id:text(c.id,100),section:sec.id,lane,text:text(c.text),status:choice(c.status,['confirm','confirmed','fixed'])||'confirm',source:text(c.source,1000),x:Math.max(0,Math.min(sec.lanes.length*300-280,Number(c.x)||lane*300+12)),y:Math.max(60,Math.min(60000,Number(c.y)||70))});
    }
    const links=[],linkIds=new Set();for(const [i,l] of (Array.isArray(b.links)?b.links:[]).slice(0,400).entries()){if(!l||!seen.has(l.from)||!seen.has(l.to)||l.from===l.to)continue;const id=typeof l.id==='string'&&/^[A-Za-z0-9_-]{1,100}$/.test(l.id)?l.id:'link-'+i;if(linkIds.has(id))continue;linkIds.add(id);links.push({id,from:l.from,to:l.to,label:text(l.label,160)});}
    const fields=(source,labels)=>Object.fromEntries(Object.keys(labels).map(k=>[k,text(source?.[k])]));
    return {revision:1,touchedAt:text(s.touchedAt,80),frameReviewed:s.frameReviewed===true,alignmentReviewed:s.alignmentReviewed===true,confidence:choice(s.confidence,['yes','no']),confidenceNote:text(s.confidenceNote),checks:Object.fromEntries(Object.keys(expected).map(k=>[k,s.checks?.[k]===true])),warnings:(Array.isArray(s.warnings)?s.warnings:[]).filter(k=>k in warningLabels),returnStandard:choice(s.returnStandard,['yes','no']),routeDecision:choice(s.routeDecision,['limited','stop']),decisionNote:text(s.decisionNote),decisionOwner:text(s.decisionOwner,300),postmortem:text(s.postmortem,10000),alignment:fields(s.alignment,alignmentLabels),limited:fields(s.limited,limitedLabels),history:cleanHistory(s.history),board:{cards,links,section:sectionById(b.section).id,timings:Object.fromEntries(sections.map(sec=>[sec.id,Math.max(1,Math.min(240,Math.round(Number(b.timings?.[sec.id]))||sec.minutes))]))},mandate:{mode:choice(m.mode,['email','presentation'])||'email',draft:text(m.draft,50000),status:choice(m.status,['draft','sent','validated','changes'])||'draft',client:text(m.client,300),sponsor:text(m.sponsor,300),date:validDate(m.date)?m.date:'',reference:text(m.reference,2000),needsReview:!!m.needsReview,versions:(Array.isArray(m.versions)?m.versions:[]).slice(-20).map(v=>({at:text(v.at,80),status:text(v.status,40),draft:text(v.draft,50000),client:text(v.client,300),sponsor:text(v.sponsor,300),date:text(v.date,40),reference:text(v.reference,2000),mode:choice(v.mode,['email','presentation'])||'email'}))}};
  }
  function state(p=project()){return p.kickoff??=clean();}
  function event(k,field,value){k.history.push({at:now(),field,value:String(value).slice(0,4000)});k.history=k.history.slice(-100);}
  function invalidate(p,routeChanged=false){
    const k=state(p);if(!k.touchedAt)return;
    if(k.confidence)event(k,'Previous confidence',k.confidence);
    k.confidence='';k.frameReviewed=false;
    if(routeChanged){k.returnStandard='';k.alignmentReviewed=false;if(k.routeDecision!=='stop')k.routeDecision='';}
    if(['sent','validated'].includes(k.mandate.status))k.mandate.needsReview=true;
  }
  function snapshotMandate(k){const m=k.mandate;if(m.draft) m.versions.push({at:now(),status:m.status,draft:m.draft,client:m.client,sponsor:m.sponsor,date:m.date,reference:m.reference,mode:m.mode});m.versions=m.versions.slice(-20);}
  function mutate(fn,refresh=true){
    const p=project(),before=clone({kickoff:state(p),context:p.context,readiness:p.readiness,methodSelection:p.methodSelection});
    if(!state(p).touchedAt)event(state(p),'Entry route',route(p));fn(state(p),p);state(p).touchedAt=now();state(p).board.section=section;save();
    if(api.failed()){Object.assign(p,before);if(refresh)render();else updateChrome();toast('This change could not be saved. Your previous work is unchanged.');return false;}
    if(refresh)render();else updateChrome();return true;
  }
  function route(p=project()){
    const k=state(p),r=p.readiness||{},constrained=['partial','locked'].includes(p.context.constraint)||r.assessment==='no';
    const readinessStopped=r.assessment==='no'&&r.constraint==='locked'&&['hold','stop'].includes(r.decision);
    if(k.routeDecision==='stop')return 'stop';
    if(readinessStopped)return r.decision==='stop'?'stop':'hold';
    if(k.routeDecision==='limited'&&k.returnStandard==='no')return 'limited';
    if(k.returnStandard==='yes')return 'standard';
    if(k.returnStandard==='no')return 'alignment';
    if(constrained||k.confidence==='no')return 'alignment';
    return r.assessment==='yes'?'standard':'unassessed';
  }
  function progress(p=project()){
    const k=state(p),r=route(p),adapted=['limited','stop'].includes(r);
    return [adapted?k.alignmentReviewed:k.frameReviewed,(r==='standard'&&k.confidence==='yes')||(adapted&&!!k.decisionOwner.trim()&&!!k.decisionNote.trim()),['standard','limited'].includes(r)&&k.mandate.status==='validated'&&!k.mandate.needsReview&&!!k.mandate.client.trim()&&!!k.mandate.sponsor.trim()&&!!k.mandate.date];
  }
  const button=(label,action,id='',extra='')=>`<button type="button" class="button small" data-action="kf-${action}" data-id="${esc(id)}" ${extra}>${label}</button>`;
  const field=(label,path,value,opts='')=>`<label class="kf-field">${label}<textarea rows="2" maxlength="4000" data-kf-field="${path}" ${opts}>${esc(value)}</textarea></label>`;
  const choices=(label,path,value,items)=>`<fieldset class="readiness-choice-group"><legend>${label}</legend><div class="readiness-choices">${items.map(([id,title])=>`<label class="readiness-choice ${id===value?'selected':''}"><input type="radio" name="kf-${path}" data-kf-choice="${path}" value="${id}" ${id===value?'checked':''}><span>${title}</span></label>`).join('')}</div>${value&&path!=='mandate.mode'?button('Clear answer','clear',path):''}</fieldset>`;
  const badge=(done,label='Reviewed')=>`<span class="readiness-badge ${done?'reviewed':''}">${done?label:'To review'}</span>`;
  function milestone(number,title,done,body){return `<section class="readiness-milestone"><header><span class="milestone-number">${number}</span><div><p class="eyebrow">MILESTONE ${number}</p><h2>${title}</h2></div>${badge(done)}</header><div class="readiness-step">${body}</div></section>`;}
  function help(){return `<section class="kf-help"><h2>Need help?</h2><p>Contact the UX Research guild.</p><a class="text-link" href="#help-center">Open Help center →</a></section>`;}
  function resources(){return `<aside class="readiness-resources" aria-label="Resources in this step"><section><h2>Templates in this step</h2><a class="readiness-resource" href="#activity/frame-problem"><strong>Framing canvas</strong><span>Editable board</span></a><a class="readiness-resource" href="#activity/align-constraints"><strong>UX & business alignment</strong><span>Focused agreement</span></a><a class="readiness-resource" href="#activity/design-mandate"><strong>Design mandate</strong><span>Email or presentation outline</span></a></section><section><h2>Guides in this step</h2><p>Short prompts are included in each activity.</p></section>${help()}</aside>`;}
  function banner(){const k=state(),r=route();const title={standard:'Standard framing',alignment:k.confidence==='no'?'Clarify the frame through alignment':'Start with UX & business alignment',limited:'A limited design approach',stop:'Intervention stopped',hold:'Paused for review',unassessed:'Choose a starting route'}[r];return `<section class="kf-route ${r==='stop'||r==='hold'?'kf-caution':''}"><p class="eyebrow">YOUR STARTING ROUTE</p><h2>${title}</h2><p>${r==='unassessed'?'Review the starting conditions, or explore any activity below.':r==='alignment'?'Agree what is fixed, what can change and which useful decision design can still support.':r==='limited'?'Keep the agreed effort, outputs and evidence limitations visible in the mandate.':r==='hold'||r==='stop'?'You can browse and keep notes. The recorded decision remains until you explicitly reopen the approach review.':'Build a shared frame, review its confidence and agree the design mandate.'}</p>${r==='unassessed'?`<a class="text-link" href="#phase/readiness">Review UX readiness →</a> ${button('Use standard framing','standard')}${button('Review a constrained approach','alignment')}`:''}${r==='hold'||r==='stop'?button('Reopen approach review','reopen'):''}</section>`;}
  function decisionTrail(){
    const k=state(),last=(name)=>k.history.slice().reverse().find(e=>e.field===name)?.value;
    const origin=last('Starting route')||k.history.find(e=>e.field==='Entry route')?.value;
    const confidence=k.confidence||last('Confidence')||last('Previous confidence');
    if(!origin&&!confidence&&!k.returnStandard&&!k.routeDecision)return '';
    return `<section class="kf-decision-trail" aria-label="Decision trail"><p class="eyebrow">DECISIONS SO FAR</p><ol>${origin?`<li><strong>Starting route</strong><span>${esc(({standard:'Standard framing',alignment:'UX & business alignment',unassessed:'Starting conditions reviewed here',stop:'Stopped intervention',hold:'Paused for review'})[origin]||origin)}</span></li>`:''}${confidence?`<li><strong>Framing confidence</strong><span>${confidence==='yes'?'Yes':'No · clarify through alignment'}${!k.confidence?' · earlier decision; review after updates':''}</span></li>`:''}${k.returnStandard?`<li><strong>After alignment: return to standard?</strong><span>${k.returnStandard==='yes'?'Yes · update the frame and review confidence again':'No · agree a limited approach or stop'}</span></li>`:''}${k.routeDecision?`<li><strong>Agreed approach</strong><span>${k.routeDecision==='limited'?'Limited design mandate':'Stop · internal post-mortem'}</span></li>`:''}</ol></section>`;
  }
  function confidencePanel(){const k=state();return `<h3>Are we confident in this framing?</h3><p>Review what the workshop established. A difficult or shortened session may leave gaps worth clarifying.</p><fieldset class="kf-checks"><legend>Expected outcomes</legend>${Object.entries(expected).map(([id,label])=>`<label><input type="checkbox" data-kf-check="${id}" ${k.checks[id]?'checked':''}>${label}</label>`).join('')}</fieldset><details class="kf-warnings"><summary>Warning signs${k.warnings.length?' · '+k.warnings.length+' recorded':''}</summary>${Object.entries(warningLabels).map(([id,label])=>`<label><input type="checkbox" data-kf-warning="${id}" ${k.warnings.includes(id)?'checked':''}>${label}</label>`).join('')}</details><p class="kf-gap">${Object.values(k.checks).filter(Boolean).length} of 5 outcomes reviewed. Gaps and warnings support your judgement; they do not calculate confidence.</p>${choices('Is this frame clear enough to proceed?','confidence',k.confidence,[['yes','Yes'],['no','No']])}${field('Confidence notes / remaining gaps (optional)','confidenceNote',k.confidenceNote)}${k.confidence==='no'?`<section class="kf-next-decision"><p><strong>Framing needs clarification.</strong> Use UX & business alignment, then record the next decision below.</p><a class="text-link" href="#activity/align-constraints">Open the alignment activity →</a>${alignmentPanel()}</section>`:''}`;}
  function alignmentPanel(){const k=state();return `<section id="kfAlignmentDecision" class="kf-next-decision"><h3>After alignment: can we return to standard framing?</h3><p>Design and project decision makers review the available room, user access and the agreed UX role. Include the Design Lead / Head of Design, and UXR where useful.</p>${choices('Return to standard framing?','returnStandard',k.returnStandard,[['yes','Yes'],['no','No']])}${k.returnStandard==='yes'?'<p>Return to the existing framing board, fill the gaps and review confidence again.</p><a class="button" href="#activity/frame-problem">Update the framing →</a>':k.returnStandard==='no'?`<section id="kfLimitedDecision"><h3>Next decision: limited approach or stop</h3>${choices('Agree the next approach','routeDecision',k.routeDecision,[['limited','Limited approach'],['stop','Stop the intervention']])}${field('Decision owner(s)','decisionOwner',k.decisionOwner)}${field('Decision and rationale','decisionNote',k.decisionNote)}</section>`:''}</section>`;}
  function page(){const k=state(),r=route(),done=progress();$('#main').innerHTML=`<article class="readiness-page kf-page" style="--color:#456e7c;--tint:#eaf1f2"><a class="back-link" href="#overview">← Home</a><div class="phase-header"><span class="phase-disc">02</span><div><p class="eyebrow">STAGE 02 / 07</p><h1>Kickoff & framing</h1><p>What are we trying to learn and decide?</p></div></div><section class="readiness-intro"><h2>Objectives for this stage</h2><p>Build a shared picture of the problem, the people affected and the outcome to pursue. Agree what design can contribute, what remains uncertain and who will validate the mandate.</p></section>${banner()}<div class="readiness-layout"><div class="readiness-main">${milestone(1,'Build or review the project frame',done[0],`<h3>${['alignment','limited','stop','hold'].includes(r)?'Clarify the essentials together':'Frame the project together'}</h3><p>${['alignment','limited','stop','hold'].includes(r)?'Use a focused alignment to agree fixed commitments, remaining choices, useful evidence and realistic outputs.':'Connect the team’s request, user difficulties and business objectives before choosing solutions.'}</p><div class="kf-actions"><a class="button primary" href="#activity/${['alignment','limited','stop','hold'].includes(r)?'align-constraints':'frame-problem'}">${['alignment','limited','stop','hold'].includes(r)?'Open alignment activity':'Open framing workshop'} →</a><a class="text-link" href="#activity/${['alignment','limited','stop','hold'].includes(r)?'frame-problem':'align-constraints'}">${['alignment','limited','stop','hold'].includes(r)?'Explore the framing workshop':'Explore UX & business alignment'} →</a></div>`)}${milestone(2,'Assess confidence and agree the approach',done[1],decisionTrail()+(['limited','stop'].includes(r)?`<h3>${r==='limited'?'Limited approach agreed':'Stop decision recorded'}</h3><p>${esc(k.decisionNote||'Record the rationale in the alignment activity.')}</p><p class="field-help">Decision owner(s): ${esc(k.decisionOwner||'Not recorded')}</p>${button('Review approach decision','reopen')}`:k.returnStandard==='no'?alignmentPanel():k.confidence==='no'?confidencePanel():['alignment','hold'].includes(r)?alignmentPanel():confidencePanel()))}${milestone(3,'Agree on the design mandate',done[2],`<p>${r==='stop'?'A stopped intervention has no mandate to validate. Retain its rationale and capture the internal learning.':'Turn the framing or alignment outputs into an agreement on objectives, scope, deliverables, effort and timing.'}</p><a class="button" href="#activity/design-mandate">Open mandate activity →</a>${r==='stop'?field('Internal post-mortem: conditions, attempts to unblock and lessons','postmortem',k.postmortem):`<p class="field-help">${k.mandate.needsReview?'The mandate needs review after a change.':k.mandate.status==='validated'?'Client/sponsor validation recorded.':k.mandate.status==='sent'?'Sent for validation; awaiting agreement.':'Draft the mandate as an email or presentation outline.'}</p>`}`)}${history(k)}</div>${resources()}</div>${stageNavigation('kickoff')}</article>`;}
  function history(k){return k.history.length?`<details class="readiness-history"><summary>Framing decision history</summary><ol>${k.history.slice().reverse().map(e=>`<li><time>${esc(new Date(e.at).toLocaleString('en-GB'))}</time><span>${esc(e.field)}: ${esc(e.value||'Cleared')}</span></li>`).join('')}</ol></details>`:'';}
  function sharedFacts(){const c=project().context;return `<details class="kf-shared"><summary>Project facts · shared with context</summary><div class="form-grid">${[['problem','Situation / agreed problem'],['decision','Decision to support'],['users','Audience notes'],['timing','Timing / key constraints']].map(([key,label])=>field(label,'context.'+key,c[key]||'')).join('')}<label>Project organisation<select data-kf-context="organisation">${organisationOptions.map(([v,l])=>`<option value="${v}" ${c.organisation===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Cadence / sprint length<input data-kf-context="cadence" maxlength="300" value="${esc(c.cadence||'')}" placeholder="e.g. 2-week sprints, monthly decisions"></label><label>Finish by<input type="date" data-kf-context="finishDate" value="${esc(c.finishDate||'')}"></label><div><a class="text-link" href="#phase/readiness">Review readiness / constraints →</a><p class="field-help">Edit user profiles and access in project context.</p></div></div></details>`;}
  const legacy=()=>['frame-problem','align-constraints','design-mandate'].some(id=>Object.values(project().notes[id]||{}).some(Boolean))||Object.values(project().templateNotes['ux-framing-canvas']||{}).some(Boolean);
  function legacyPanel(){return legacy()?`<details class="kf-legacy"><summary>Earlier activity notes and canvas drafts</summary>${['frame-problem','align-constraints','design-mandate'].map(id=>Object.entries(project().notes[id]||{}).filter(([,v])=>v).map(([key,v])=>`<h4>${esc(id+' · '+key)}</h4><p class="kf-preserve">${esc(v)}</p>`).join('')).join('')}${Object.entries(project().templateNotes['ux-framing-canvas']||{}).filter(([,v])=>v).map(([key,v])=>`<h4>${esc(key)}</h4><p class="kf-preserve">${esc(v)}</p>`).join('')}${button('Bring earlier notes into the board','legacy')}</details>`:'';}
  function frameContent(tab){const k=state();if(tab==='prepare')return `<h2>Prepare a useful framing conversation</h2><p>Bring the brief, roadmap, existing evidence, known goals and constraints. Invite the people who can explain the project and user situation, make decisions or unlock access.</p><ul><li>Flag missing or contradictory information.</li><li>Identify the actual user population and possible access routes.</li><li>Make room for project, user and business perspectives.</li></ul><p>Missing information is a useful outcome. You do not need to resolve everything before the session.</p>${sharedFacts()}${legacyPanel()}`;if(tab==='run')return `<h2>Build the frame together</h2><p>Use seven sections to connect the problem, expected outcomes, evidence gaps, users, key people and first actions.</p><ol class="kf-section-list">${sections.map(s=>`<li><strong>${s.title}</strong><p>${s.tip}</p><span>${k.board.timings[s.id]} min · suggested</span></li>`).join('')}</ol>${sharedFacts()}`;return `<h2>Review the workshop outputs</h2><p>Keep the problem, scope, users/access, objectives, assumptions, evidence questions and next actions specific. Assign an owner to important gaps.</p>${boardSummary()}<label class="kf-checkline"><input type="checkbox" data-kf-choice="frameReviewed" ${k.frameReviewed?'checked':''}>Framing outputs reviewed</label>${decisionTrail()}${confidencePanel()}${legacyPanel()}`;}
  function alignmentContent(tab){const k=state();if(tab==='prepare')return `<h2>Prepare a focused alignment</h2><p>Use this when the project is constrained or framing did not establish enough confidence. Bring the constraints, disputed points and any existing evidence.</p><p>Include the product decision owner, designer and Design Lead / Head of Design; involve the sponsor and UX Research guild where useful.</p><ul><li>Identify what is fixed and which decision can still change.</li><li>Bring realistic user-access options and their limitations.</li><li>Agree who can decide on standard, limited or stopped work.</li></ul>${sharedFacts()}`;if(tab==='run')return `<h2>Agree the smallest useful frame</h2><p>Clarify fixed commitments, room to influence, the decision needing evidence and the risk worth reducing. Agree access, an output, a deadline and honest limitations.</p>${Object.entries(alignmentLabels).map(([key,label])=>field(label,'alignment.'+key,k.alignment[key])).join('')}`;return `<h2>Capture the agreement and decision</h2><label class="kf-checkline"><input type="checkbox" data-kf-choice="alignmentReviewed" ${k.alignmentReviewed?'checked':''}>Alignment outputs reviewed</label>${decisionTrail()}${alignmentPanel()}${route()==='limited'?limitedPanel():''}${route()==='stop'?field('Internal post-mortem: why stopped, attempts to unblock, lessons and reopening conditions','postmortem',k.postmortem):''}`;}
  function limitedPanel(){const k=state();return `<section class="kf-limited"><h3>Define the limited approach</h3><p>Agree one priority decision or flow, an effort budget and concrete outputs. Consider existing evidence, a focused expert review or a direct-user check where access permits.</p><p>Expert/proxy input is not user validation. State what will remain untested and who accepts the risk.</p>${Object.entries(limitedLabels).map(([key,label])=>field(label,'limited.'+key,k.limited[key])).join('')}</section>`;}
  function mandateText(){const p=project(),k=state(),r=route(),c=p.context,m=k.mandate;const heading=r==='limited'?'Limited Design Mandate':'Design Mandate';const source=boardMarkdown(false);return `${m.mode==='email'?'Subject: '+heading+' — '+c.name+'\n\nHello,\n\nPlease review the following proposed agreement.\n\n':'# '+heading+' — '+c.name+'\n\n## 1. Purpose and scope\n\n'}Problem / situation: ${c.problem||'[To confirm]'}\nDecision to support: ${c.decision||k.alignment.decision||'[To confirm]'}\nUsers / access: ${c.users||p.profiles.map(x=>x.name).join(', ')||'[To confirm]'} / ${c.access||'unknown'}\nScope / exclusions: ${k.limited.scope||'[To confirm]'}\nOrganisation: ${c.organisation||'[To confirm]'}\nCadence: ${c.cadence||'[To confirm]'}\nTiming / finish date: ${[c.timing,c.finishDate].filter(Boolean).join(' / ')||'[To confirm]'}\n\n${m.mode==='presentation'?'## 2. Agreed project frame\n\n':''}${source}\n${m.mode==='presentation'?'## 3. Contribution, outputs and conditions\n\n':''}Deliverables: ${k.limited.deliverables||k.alignment.output||'[To confirm]'}\nEffort budget (person-days): ${k.limited.effort||'[To confirm]'}\nConstraints / limitations: ${[c.constraint,k.alignment.limitations,k.limited.risks].filter(Boolean).join(' · ')||'[To confirm]'}\nFollow-up: ${k.limited.followup||'[To confirm]'}\nDecision owners / rationale: ${[k.decisionOwner,k.decisionNote].filter(Boolean).join(' · ')||'[To confirm]'}\n\n${m.mode==='presentation'?'## 4. Validation requested\n\n':''}Please confirm the objectives, scope, outputs, timing and remaining conditions, or identify the changes needed.\nClient validation: [Pending]\nSponsor validation: [Pending]\n`;}
  function mandateContent(tab){const k=state(),m=k.mandate,r=route();if(tab==='prepare')return `<h2>Prepare the agreement</h2><p>Bring the framing or alignment outputs and the explicit route decision. Identify the client and sponsor who will validate the objectives, scope, deliverables and timing.</p><p>A short email may suit a small project; a presentation outline can support a wider discussion. Both need the same agreement.</p>${r==='limited'?limitedPanel():''}${sharedFacts()}<a class="text-link" href="#activity/frame-problem">Review the framing →</a>`;if(tab==='run')return `<h2>${r==='limited'?'Draft the limited design mandate':'Draft the design mandate'}</h2>${!['standard','limited'].includes(r)||r==='standard'&&k.confidence!=='yes'?'<p class="kf-caution">You can draft now. Review confidence or the limited-approach decision before recording validation.</p>':''}${choices('How will you present the agreement?','mandate.mode',m.mode,[['email','Email'],['presentation','Presentation outline']])}<div class="kf-actions">${button(m.draft?'Refresh draft from workshop data':'Create draft from workshop data','generate')}${button('Download mandate (.md)','mandate-export')}</div>${m.needsReview?'<p class="kf-caution">The project or workshop changed after this mandate was sent/validated. Review the draft and record validation again.</p>':''}<label class="kf-field">Editable mandate draft<textarea rows="20" maxlength="50000" data-kf-field="mandate.draft">${esc(m.draft)}</textarea></label>${m.versions.length?`<details><summary>Earlier mandate versions · ${m.versions.length}</summary>${m.versions.slice().reverse().map(v=>`<details><summary>${esc(v.at)} · ${esc(v.status)}</summary><pre class="kf-preserve">${esc(v.draft)}</pre></details>`).join('')}</details>`:''}`;return `<h2>Record client and sponsor validation</h2><p>Sending the mandate leaves it awaiting validation. Complete this activity after both approvals are recorded; a presentation or email can be the reference.</p><p><strong>Current status:</strong> ${esc(({draft:'Draft',sent:'Sent for validation',validated:'Validated',changes:'Changes requested'})[m.status])}${m.needsReview?' · Review needed':''}</p>${field('Client approval · name / role','mandate.client',m.client)}${field('Sponsor approval · name / role','mandate.sponsor',m.sponsor)}<label class="kf-field">Validation date<input type="date" data-kf-field="mandate.date" value="${esc(m.date)}"></label>${field('Validation reference / agreed conditions','mandate.reference',m.reference)}<div class="kf-actions">${button('Mark sent for validation','mandate-status','sent')}${button('Record validation','mandate-status','validated')}${button('Changes requested','mandate-status','changes')}</div>${r==='stop'?`<p>The intervention is stopped. Capture the internal post-mortem instead of completing a mandate.</p>${field('Internal post-mortem','postmortem',k.postmortem)}`:''}`;}
  function activity(id,tab){if(!['frame-problem','align-constraints','design-mandate'].includes(id))return false;const title={ 'frame-problem':'Framing workshop','align-constraints':'UX & business alignment','design-mandate':'Agree on the design mandate'}[id];if(!title)return false;$('#main').innerHTML=`<article class="kf-activity" style="--color:#456e7c;--tint:#eaf1f2"><a class="back-link" href="#phase/kickoff">← Kickoff & framing</a><p class="eyebrow">${id==='design-mandate'?'AGREEMENT':'WORKSHOP'}</p><h1>${title}</h1>${project().done.includes(id)?'<p class="field-help">Earlier activity marked complete. Its saved notes and completion record are retained.</p>':''}<p class="page-intro">${id==='frame-problem'?'Turn the project request into a shared problem, useful outcomes and a first course of action.':id==='align-constraints'?'Agree what design can still influence and which approach is viable.':'Formalise the agreed contribution and record client/sponsor validation.'}</p>${id!=='design-mandate'?button('Facilitate the workshop','facilitate',id):''}<div class="tabs" role="tablist" aria-label="Activity content">${[['prepare','01 Prepare'],['run','02 Apply'],['capture','03 Capture & check']].map(([key,label])=>`<button role="tab" id="tab-${key}" aria-selected="${tab===key}" aria-controls="activityPanel" tabindex="${tab===key?0:-1}" class="tab ${tab===key?'active':''}" data-tab="${key}">${label}</button>`).join('')}</div><div class="readiness-layout"><section class="content-panel" id="activityPanel" role="tabpanel" aria-labelledby="tab-${tab}">${id==='frame-problem'?frameContent(tab):id==='align-constraints'?alignmentContent(tab):mandateContent(tab)}</section>${resources()}</div>${stageNavigation('kickoff')}</article>`;return true;}
  function cardLabel(c){return `${sectionById(c.section).title}: ${c.text.trim().slice(0,65)||'Empty card'}`;}
  function cardHTML(c){const s=sectionById(c.section);return `<article class="kf-card ${c.status}" data-card-id="${esc(c.id)}" style="left:${c.x/(s.lanes.length*300)*100}%;width:${260/(s.lanes.length*300)*100}%;top:${c.y}px"><header><button type="button" class="kf-drag" data-kf-drag="${esc(c.id)}" aria-label="Move card ${esc(c.text.slice(0,35)||'untitled')} with arrow keys" title="Drag, or use arrow keys to move">⠿</button><span>${esc(s.lanes[c.lane])}</span>${button('×','delete-card',c.id,'aria-label="Delete card"')}</header><label><span class="sr-only">Card text</span><textarea aria-label="Card text" maxlength="4000" data-kf-card="${esc(c.id)}" data-field="text">${esc(c.text)}</textarea></label><div class="kf-card-meta"><label><span class="sr-only">Card status</span><select aria-label="Card status" data-kf-card="${esc(c.id)}" data-field="status"><option value="confirm" ${c.status==='confirm'?'selected':''}>To confirm</option><option value="confirmed" ${c.status==='confirmed'?'selected':''}>Confirmed</option><option value="fixed" ${c.status==='fixed'?'selected':''}>Fixed decision</option></select></label><label><span class="sr-only">Move to column</span><select aria-label="Move to column" data-kf-card="${esc(c.id)}" data-field="lane">${s.lanes.map((l,i)=>`<option value="${i}" ${i===c.lane?'selected':''}>${esc(l)}</option>`).join('')}</select></label></div><input aria-label="Source / reference" placeholder="Source / reference" maxlength="1000" data-kf-card="${esc(c.id)}" data-field="source" value="${esc(c.source)}"></article>`;}
  function linkPanel(){const k=state(),options=k.board.cards.map(c=>`<option value="${esc(c.id)}">${esc(cardLabel(c))}</option>`).join('');return `<details class="kf-links" ${k.board.links.length?'open':''}><summary>Connections · ${k.board.links.length}</summary><div class="kf-link-editor"><label>From<select id="kfLinkFrom">${options}</select></label><label>To<select id="kfLinkTo">${options}</select></label><label>Relationship<input id="kfLinkLabel" maxlength="160" placeholder="e.g. leads to, needs evidence"></label>${button('Connect cards','connect')}</div><ul>${k.board.links.map(l=>`<li><span>${esc(cardLabel(k.board.cards.find(c=>c.id===l.from)))} <strong>→ ${esc(l.label||'connects to')} →</strong> ${esc(cardLabel(k.board.cards.find(c=>c.id===l.to)))}</span>${button('Remove connection','delete-link',l.id)}</li>`).join('')}</ul></details>`;}
  function boardSummary(){const k=state();return `<div class="kf-board-summary"><p><strong>${k.board.cards.length} cards</strong> · ${k.board.links.length} connections</p>${button('Open the framing board','facilitate','frame-problem')}${button('Export workshop summary (.md)','summary-export')}</div>`;}
  function svgLinks(cards){const k=state();return `<svg class="kf-connectors" width="100%" height="${Math.max(620,...cards.map(c=>c.y+280))}" viewBox="0 0 ${sectionById(section).lanes.length*300} ${Math.max(620,...cards.map(c=>c.y+280))}" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="kfArrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#6c5eae"/></marker></defs>${k.board.links.map(l=>{const a=cards.find(c=>c.id===l.from),b=cards.find(c=>c.id===l.to);if(!a||!b)return '';const x=a.x+260,y=a.y+100,x2=b.x,y2=b.y+100;return `<path d="M${x},${y} C${x+60},${y} ${x2-60},${y2} ${x2},${y2}" fill="none" stroke="#6c5eae" stroke-width="2" vector-effect="non-scaling-stroke" marker-end="url(#kfArrow)"/>`;}).join('')}</svg>`;}
  function storyBoard(){const k=state(),positions=new Map();for(const [i,sec] of sections.entries())k.board.cards.filter(c=>c.section===sec.id).forEach((c,n)=>positions.set(c.id,{x:i*320+18,y:75+n*210}));const height=Math.max(520,...Array.from(positions.values()).map(p=>p.y+200));return `<div class="kf-board-scroll" tabindex="0" aria-label="Overall story, scroll across all seven sections"><div class="kf-story-surface" style="width:100%;min-width:1960px;height:${height}px">${sections.map((sec,i)=>`<div class="kf-story-lane" style="left:${i/sections.length*100}%;width:${100/sections.length}%"><h3>${i+1}. ${sec.title}</h3></div>`).join('')}<svg class="kf-connectors" width="100%" height="${height}" viewBox="0 0 2240 ${height}" preserveAspectRatio="none" aria-hidden="true"><defs><marker id="kfStoryArrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="#6c5eae"/></marker></defs>${k.board.links.map(l=>{const a=positions.get(l.from),b=positions.get(l.to);if(!a||!b)return '';const x=a.x+260,y=a.y+80,x2=b.x,y2=b.y+80;return `<path d="M${x},${y} C${x+70},${y} ${x2-70},${y2} ${x2},${y2}" fill="none" stroke="#6c5eae" stroke-width="2" vector-effect="non-scaling-stroke" marker-end="url(#kfStoryArrow)"/>`;}).join('')}</svg>${k.board.cards.map(c=>{const pos=positions.get(c.id);return `<article class="kf-story-card ${c.status}" style="left:${pos.x/2240*100}%;width:${260/2240*100}%;top:${pos.y}px"><p class="eyebrow">${esc(sectionById(c.section).lanes[c.lane])}</p><p>${esc(c.text||'Empty card')}</p><small>${c.status==='confirmed'?'Confirmed':c.status==='fixed'?'Fixed decision':'To confirm'}</small>${button('Open section','section',c.section)}</article>`;}).join('')}</div></div>`;}
  function timeLabel(){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
  function stopTimer(){if(timer)clearInterval(timer);timer=null;}
  function timerPanel(){return `<div class="timer kf-section-timer"><span class="timer-label">Section timer</span><output id="kfTimer" aria-label="Workshop time remaining">${timeLabel()}</output><label class="kf-timer-duration">Minutes<input type="number" min="1" max="240" step="1" aria-label="Section duration in minutes" data-kf-timing="${section}" value="${state().board.timings[section]}"></label>${button(timer?'Pause timer':'Start timer','timer')}${button('Reset timer','timer-reset')}</div>`;}
  function renderSession(){const k=state(),s=sectionById(section);document.body.classList.add('focus-mode');updateChrome();$('#main').innerHTML=`<section class="kf-session"><div class="workshop-top"><div><p class="eyebrow">FACILITATION MODE</p><h1>${session==='align-constraints'?'UX & business alignment':'Framing workshop'}</h1></div>${button('Exit session ✕','exit')}</div>${session==='align-constraints'?`<p class="page-intro">Clarify the essentials and agree a viable approach.</p>${alignmentContent('run')}${button('Capture & review the decision →','capture','align-constraints')}`:`<div class="kf-board-toolbar"><label class="kf-mobile-section">Workshop section<select data-kf-section="true">${sections.map(sec=>`<option value="${sec.id}" ${sec.id===section?'selected':''}>${sec.title}</option>`).join('')}</select></label><nav aria-label="Workshop sections">${sections.map((sec,i)=>button(`${i+1}. ${sec.title}`,'section',sec.id,sec.id===section&&!overview?'aria-current="step"':'')).join('')}</nav><div class="kf-actions">${button('Overall story','overview')}${button('Export summary (.md)','summary-export')}<button type="button" class="button small" data-action="export">Export project (.json)</button></div></div>${overview?`<h2>The overall story</h2>${storyBoard()}`:`<div class="kf-section-heading"><div><p class="eyebrow">SECTION ${sections.indexOf(s)+1} / ${sections.length}</p><h2>${s.title}</h2><p>${s.tip}</p></div>${timerPanel()}</div><div class="kf-actions">${button('+ Add a card','add-card',s.id)}${undo?.projectId===project().id?button('Undo card deletion','undo-card'):''}<span class="field-help">Drag the handle or use its arrow keys. Connections stay visible on the board.</span></div><div class="kf-board-scroll" tabindex="0" aria-label="Framing board, scroll horizontally for more columns"><div class="kf-board-surface" style="width:100%;min-width:${s.lanes.length*280}px;height:${Math.max(620,...k.board.cards.filter(c=>c.section===section).map(c=>c.y+280))}px">${s.lanes.map((label,i)=>`<div class="kf-lane" style="left:${i/s.lanes.length*100}%;width:${100/s.lanes.length}%"><h3>${esc(label)}</h3></div>`).join('')}${svgLinks(k.board.cards.filter(c=>c.section===section))}${k.board.cards.filter(c=>c.section===section).map(c=>cardHTML(c)).join('')}</div></div><div class="kf-session-nav">${button('← Previous section','section',sections[Math.max(0,sections.indexOf(s)-1)].id)}${button(sections.indexOf(s)===sections.length-1?'Review outputs →':'Next section →',sections.indexOf(s)===sections.length-1?'capture':'section',sections.indexOf(s)===sections.length-1?'frame-problem':sections[Math.min(sections.length-1,sections.indexOf(s)+1)].id)}</div>`}${linkPanel()}${sharedFacts()}${legacyPanel()}`}</section>`;}
  function boardMarkdown(includeHeading=true){const k=state();return `${includeHeading?'# Framing workshop — '+project().context.name+'\n\n':''}${sections.map(sec=>`## ${sec.title}\n\n${k.board.cards.filter(c=>c.section===sec.id).map(c=>`- [${c.id}] ${sec.lanes[c.lane]}: ${c.text||'[Not captured]'}\n  Status: ${c.status==='confirmed'?'Confirmed':c.status==='fixed'?'Fixed decision':'To confirm'}${c.source?' · Source: '+c.source:''}`).join('\n')||'[Not captured]'}`).join('\n\n')}\n\n## Connections\n\n${k.board.links.map(l=>`- [${l.from}] → ${l.label||'connects to'} → [${l.to}]`).join('\n')||'None recorded.'}\n`;}
  function markdown(){const k=state();if(!k.touchedAt)return '';return `\n## Kickoff & framing\n\nRoute: ${route()}\nConfidence: ${k.confidence||'Not reviewed'}\nConfidence notes: ${k.confidenceNote||'None'}\n\n${boardMarkdown(false)}\n## UX & business alignment\n\n${Object.entries(alignmentLabels).map(([key,label])=>`- ${label} ${k.alignment[key]||'[Not captured]'}`).join('\n')}\n\nReturn to standard: ${k.returnStandard||'Not reviewed'}\nDecision: ${k.routeDecision||'Not recorded'}\nOwner: ${k.decisionOwner||'Not recorded'}\nRationale: ${k.decisionNote||'Not recorded'}\n\n## Limited approach\n\n${Object.entries(limitedLabels).map(([key,label])=>`- ${label}: ${k.limited[key]||'[Not captured]'}`).join('\n')}\n\n## Design mandate — ${k.mandate.status}${k.mandate.needsReview?' / review needed':''}\n\n${k.mandate.draft||'[Not drafted]'}\n\nClient: ${k.mandate.client||'Pending'}\nSponsor: ${k.mandate.sponsor||'Pending'}\nValidation date: ${k.mandate.date||'Pending'}\nReference: ${k.mandate.reference||'None'}\n\n## Internal post-mortem\n\n${k.postmortem||'Not recorded.'}\n\n## Framing history\n\n${k.history.map(e=>`- ${e.at} · ${e.field}: ${e.value}`).join('\n')}\n`;}
  function start(id){stopTimer();session=id;section=state().board.section;seconds=state().board.timings[section]*60;overview=false;render();}
  function end(){stopTimer();session=null;drag=null;}
  function clearApproach(k){event(k,'Previous approach',JSON.stringify({confidence:k.confidence,returnStandard:k.returnStandard,decision:k.routeDecision}));k.confidence='';k.returnStandard='';k.routeDecision='';}
  function action(action,id,element){if(!action.startsWith('kf-'))return false;const a=action.slice(3),k=state();
    if(a==='facilitate'){start(id);return true;}
    if(a==='exit'){end();render();return true;}
    if(a==='capture'){end();api.goActivity(id||'frame-problem','capture');return true;}
    if(a==='section'){stopTimer();section=sectionById(id).id;seconds=state().board.timings[section]*60;overview=false;render();return true;}
    if(a==='overview'){stopTimer();overview=true;render();return true;}
        if(a==='timer'){if(timer)stopTimer();else if(seconds>0)timer=setInterval(()=>{seconds=Math.max(0,seconds-1);const el=$('#kfTimer');if(el)el.textContent=timeLabel();if(!seconds){stopTimer();render();toast('Section time is up. Continue when the team is ready.');}},1000);render();return true;}
    if(a==='timer-reset'){stopTimer();seconds=state().board.timings[section]*60;render();return true;}
    if(a==='summary-export'){download('framing-workshop.md',boardMarkdown(),'text/markdown;charset=utf-8');return true;}
    if(a==='mandate-export'){download('design-mandate.md',k.mandate.draft||mandateText(),'text/markdown;charset=utf-8');return true;}
    if(a==='standard')mutate((k,p)=>{clearApproach(k);syncContext(p,{constraint:'open'});recordReadiness(p.readiness,'assessment','yes');p.readiness.touchedAt=now();event(k,'Starting route','Standard framing');});
    if(a==='alignment')mutate((k,p)=>{clearApproach(k);recordReadiness(p.readiness,'assessment','no');p.readiness.touchedAt=now();event(k,'Starting route','Alignment');});
    if(a==='reopen')mutate((k,p)=>{clearApproach(k);if(p.readiness.decision){recordReadiness(p.readiness,'decision','');p.readiness.touchedAt=now();}k.mandate.needsReview=!!k.mandate.draft;event(k,'Approach review','Explicitly reopened');});
    if(a==='clear')mutate(k=>{const parts=id.split('.');if(parts.length===2)k[parts[0]][parts[1]]='';else k[id]='';event(k,id,'Cleared');});
    if(a==='add-card'){
      if(k.board.cards.length>=200){toast('This board has 200 cards. Group or export the current notes before adding more.');return true;}
      mutate((k,p)=>{invalidate(p);const s=sectionById(id),count=k.board.cards.filter(c=>c.section===s.id).length,lane=count%s.lanes.length;k.board.cards.push({id:newId(),section:s.id,lane,text:'',status:'confirm',source:'',x:lane*300+12,y:Math.max(-200,...k.board.cards.filter(c=>c.section===s.id&&c.lane===lane).map(c=>c.y))+270});});
    }
    if(a==='delete-card'){const c=k.board.cards.find(c=>c.id===id);if(c){const record={projectId:project().id,card:clone(c),links:clone(k.board.links.filter(l=>l.from===id||l.to===id))};if(mutate((k,p)=>{invalidate(p);k.board.cards=k.board.cards.filter(c=>c.id!==id);k.board.links=k.board.links.filter(l=>l.from!==id&&l.to!==id);})) {undo=record;render();}}}
    if(a==='undo-card'&&undo?.projectId===project().id){if(k.board.cards.length>=200){toast('Make room on the board before restoring this card.');return true;}const previous=undo;if(mutate((k,p)=>{invalidate(p);if(!k.board.cards.some(c=>c.id===previous.card.id))k.board.cards.push(previous.card);for(const l of previous.links)if(k.board.cards.some(c=>c.id===l.from)&&k.board.cards.some(c=>c.id===l.to)&&!k.board.links.some(x=>x.id===l.id))k.board.links.push(l);})){undo=null;render();}}
    if(a==='connect'){const from=$('#kfLinkFrom').value,to=$('#kfLinkTo').value,label=$('#kfLinkLabel').value.trim().slice(0,160);if(from===to||!k.board.cards.some(c=>c.id===from)||!k.board.cards.some(c=>c.id===to)){toast('Choose two different cards to connect.');return true;}if(k.board.links.some(l=>l.from===from&&l.to===to&&l.label===label)){toast('This connection already exists.');return true;}if(k.board.links.length>=400){toast('The board has reached 400 connections.');return true;}mutate((k,p)=>{invalidate(p);k.board.links.push({id:newId(),from,to,label});});}
    if(a==='delete-link')mutate((k,p)=>{invalidate(p);k.board.links=k.board.links.filter(l=>l.id!==id);});
    if(a==='legacy')mutate((k,p)=>{invalidate(p);const notes=[...Object.entries(p.templateNotes['ux-framing-canvas']||{}).filter(([,v])=>v),...['frame-problem','align-constraints','design-mandate'].flatMap(id=>Object.entries(p.notes[id]||{}).filter(([,v])=>v).map(([key,v])=>[id+' / '+key,v]))];const map={known:'today',assumed:'today',unclear:'today',fixed:'today',team:'problem',users:'problem',business:'problem',outcome:'success',signal:'success',measure:'success',baseline:'success',questions:'evidence',risk:'evidence',needed:'evidence',reuse:'evidence',profiles:'reach',access:'reach',route:'reach',stakeholders:'people',dependencies:'people',actions:'next',blockers:'next'};for(const [key,value] of notes){const source='Earlier notes: '+key;if(k.board.cards.some(c=>c.source===source)||k.board.cards.length>=200)continue;const sec=map[key]||'today',count=k.board.cards.filter(c=>c.section===sec).length;k.board.cards.push({id:newId(),section:sec,lane:0,text:text(value),status:'confirm',source,x:12,y:70+count*270});}event(k,'Earlier notes','Copied into cards; originals retained');});
    if(a==='generate')mutate(k=>{snapshotMandate(k);k.mandate.draft=mandateText();k.mandate.status='draft';k.mandate.needsReview=false;event(k,'Mandate','Draft generated from current workshop data');});
    if(a==='mandate-status'){
      if(id==='validated'&&(!['standard','limited'].includes(route())||route()==='standard'&&k.confidence!=='yes'||!k.mandate.draft.trim()||!k.mandate.client.trim()||!k.mandate.sponsor.trim()||!validDate(k.mandate.date)||(route()==='limited'&&(!k.decisionOwner.trim()||!k.decisionNote.trim())))){toast('Record the agreed approach, mandate draft, client and sponsor approvals, and validation date first. You can still browse every stage.');return true;}
      if(id==='sent'&&!k.mandate.draft.trim()){toast('Create or write the mandate draft before marking it sent.');return true;}
      mutate(k=>{snapshotMandate(k);k.mandate.status=id;k.mandate.needsReview=false;event(k,'Mandate status',id);});
    }
    return true;
  }
  function onInput(target,change=false){const d=target.dataset||{};if(d.kfSection){if(change){stopTimer();section=sectionById(target.value).id;seconds=state().board.timings[section]*60;overview=false;render();}return true;}
    if(d.kfCard){const c=state().board.cards.find(c=>c.id===d.kfCard);if(!c)return true;const f=d.field;if(['text','source'].includes(f)){mutate((k,p)=>{invalidate(p);k.board.cards.find(c=>c.id===d.kfCard)[f]=text(target.value,f==='source'?1000:4000);},false);}else if(change&&['status','lane'].includes(f))mutate((k,p)=>{invalidate(p);const c=k.board.cards.find(c=>c.id===d.kfCard);if(f==='lane'){c.lane=Math.min(sectionById(c.section).lanes.length-1,Math.max(0,Number(target.value)||0));c.x=c.lane*300+12;}else c.status=choice(target.value,['confirm','confirmed','fixed'])||'confirm';});return true;}
    if(d.kfContext){if(change)mutate((k,p)=>syncContext(p,{[d.kfContext]:text(target.value,300)}),false);return true;}
    if(d.kfTiming){const value=Number(target.value);if(!change&&(!target.value||!Number.isFinite(value)||value<1||value>240))return true;const minutes=Math.max(1,Math.min(240,Math.round(value)||1));if(minutes!==state().board.timings[d.kfTiming]){stopTimer();seconds=minutes*60;mutate(k=>{k.board.timings[d.kfTiming]=minutes;},change);const output=$('#kfTimer');if(output)output.textContent=timeLabel();const toggle=document.querySelector('[data-action="kf-timer"]');if(toggle)toggle.textContent='Start timer';}if(change)target.value=String(minutes);return true;}
    if(d.kfField){const path=d.kfField.split('.');mutate((k,p)=>{if(['decisionNote','decisionOwner'].includes(path[0])&&['sent','validated'].includes(k.mandate.status))k.mandate.needsReview=true;if(['alignment','limited'].includes(path[0])){invalidate(p);if(path[0]==='alignment')k.alignmentReviewed=false;}if(path[0]==='context'){syncContext(p,{[path[1]]:text(target.value)});return;}if(path[0]==='mandate'&&['sent','validated'].includes(k.mandate.status)){snapshotMandate(k);k.mandate.status='draft';k.mandate.needsReview=true;}if(path.length===2)k[path[0]][path[1]]=text(target.value,path[1]==='draft'?50000:4000);else k[path[0]]=text(target.value,path[0]==='postmortem'?10000:4000);},false);return true;}
    if(d.kfChoice){if(!change)return true;mutate((k,p)=>{const path=d.kfChoice.split('.'),value=target.type==='checkbox'?target.checked:target.value;if(path[0]==='returnStandard'){
      event(k,'Return to standard',value);k.routeDecision='';if(value==='yes'){k.frameReviewed=false;k.confidence='';syncContext(p,{constraint:'open'});recordReadiness(p.readiness,'assessment','yes');p.readiness.touchedAt=now();}k.returnStandard=value;
    }else if(path[0]==='confidence'){k.confidence=value;if(value==='no'){k.returnStandard='';k.routeDecision='';k.alignmentReviewed=false;}event(k,'Confidence',value);if(['sent','validated'].includes(k.mandate.status))k.mandate.needsReview=true;
    }else if(path[0]==='routeDecision'){k.routeDecision=value;event(k,'Approach decision',value);if(['sent','validated'].includes(k.mandate.status))k.mandate.needsReview=true;
    }else if(path.length===2){if(path[0]==='mandate'&&['sent','validated'].includes(k.mandate.status)){snapshotMandate(k);k.mandate.status='draft';k.mandate.needsReview=true;}k[path[0]][path[1]]=value;}else k[path[0]]=value;});if(target.value==='no'&&d.kfChoice==='confidence')document.getElementById('kfAlignmentDecision')?.scrollIntoView?.({behavior:'smooth',block:'nearest'});if(target.value==='no'&&d.kfChoice==='returnStandard')document.getElementById('kfLimitedDecision')?.scrollIntoView?.({behavior:'smooth',block:'nearest'});return true;}
    if(d.kfCheck||d.kfWarning){if(change)mutate(k=>{if(d.kfCheck)k.checks[d.kfCheck]=target.checked;else k.warnings=target.checked?[...new Set([...k.warnings,d.kfWarning])]:k.warnings.filter(id=>id!==d.kfWarning);});return true;}
    return false;
  }
  function moveCard(id,x,y){mutate((k,p)=>{const c=k.board.cards.find(c=>c.id===id);if(!c)return;c.x=Math.max(0,Math.min(sectionById(c.section).lanes.length*300-280,x));c.y=Math.max(60,Math.min(60000,y));c.lane=Math.min(sectionById(c.section).lanes.length-1,Math.floor((c.x+130)/300));});document.querySelector(`[data-kf-drag="${id}"]`)?.focus();}
  function keydown(e){const handle=e.target.closest?.('[data-kf-drag]');if(!handle||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return false;const c=state().board.cards.find(c=>c.id===handle.dataset.kfDrag);if(!c)return false;e.preventDefault();moveCard(c.id,c.x+(e.key==='ArrowLeft'?-20:e.key==='ArrowRight'?20:0),c.y+(e.key==='ArrowUp'?-20:e.key==='ArrowDown'?20:0));return true;}
  function pointerdown(e){const h=e.target.closest?.('[data-kf-drag]');if(!h||overview)return;const c=state().board.cards.find(c=>c.id===h.dataset.kfDrag);if(!c)return;drag={id:c.id,x:c.x,y:c.y,startX:e.clientX,startY:e.clientY,scale:(h.closest('.kf-board-surface')?.clientWidth||sectionById(c.section).lanes.length*300)/(sectionById(c.section).lanes.length*300),element:h.closest('[data-card-id]')};h.setPointerCapture?.(e.pointerId);e.preventDefault();}
  function pointermove(e){if(drag?.element)drag.element.style.transform=`translate(${e.clientX-drag.startX}px,${e.clientY-drag.startY}px)`;}
  function pointerup(e){if(!drag)return;const d=drag;drag=null;moveCard(d.id,d.x+(e.clientX-d.startX)/d.scale,d.y+e.clientY-d.startY);}
  return {clean,state,progress,route,invalidate,page,activity,action,onInput,keydown,pointerdown,pointermove,pointerup,start,end,renderSession,active:()=>!!session,markdown};
};
